solution:
VAT_RATE = 0.23
DISCOUNT_RATE = 0.10
DISCOUNT_FROM = 200


def invoice_total(prices):
    subtotal = sum(prices)
    if subtotal >= DISCOUNT_FROM:
        subtotal *= 1 - DISCOUNT_RATE
    return round(subtotal * (1 + VAT_RATE), 2)

